-- Holiday Inn treatment menu transcribed from "Holiday menu.pdf".
-- Prices are stored in paise. Membership packages are intentionally excluded:
-- they are financial products, not appointment treatment variants.

ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  treatment_name = EXCLUDED.treatment_name,
  variant_name = EXCLUDED.variant_name,
  duration = EXCLUDED.duration,
  price_paise = EXCLUDED.price_paise,
  active = EXCLUDED.active,
  centre_id = EXCLUDED.centre_id;
